/* Consulta realizada:
SELECT '"' + RTRIM(LTRIM(D3_COD)) + '": ' + '{"descricao": "' + RTRIM(LTRIM(REPLACE(B1_DESC, '"', '\"'))) + '", "um": "' + RTRIM(LTRIM(B1_UM)) + '"},'
FROM SD3010 
INNER JOIN SB1010 ON B1_COD = D3_COD AND SB1010.D_E_L_E_T_ = ''
WHERE 
    D3_TM = '201' 
    AND D3_ESTORNO = '' 
    AND SD3010.D_E_L_E_T_ = ''
    AND D3_EMISSAO >= '20200101'
    AND ((B1_MSBLQL != '1') OR (B1_MSBLQD = '' OR B1_MSBLQD < '20261231'))
    AND B1_DESC NOT LIKE '%FORA DE USO%' 
    AND SD3010.D_E_L_E_T_ = ''
GROUP BY D3_COD, B1_DESC, B1_UM
ORDER BY D3_COD ASC
*/